 MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	notStationeryAware,					reserved,	reserved,	reserved,	reserved,		/* Suggested partition size */	(1000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,		/* Minimum partition size */	(800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif // !MW_Rez//--------------------------------------------------------------------------------------------------// Memory usage information for Moviewer//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------// MacApp memory management -- see "Memory.r" and "UMemory.cpp"resource 'mem!' (130,#if qNames	"Application",#endif	purgeable) {	0,						// Pointer-based object allocation heap size (initial)	0,						// Min size by which to grow object heap	20 * 1024,				// Add to temporary reserve (code reserve)	20 * 1024,				// Add to permanent reserve	0						// Base stack size. };//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x20,	alpha,	0x04,	verUs,	"1.2a4",	"Scriptable Movie Viewer 1.2a4, ©Apple Computer, Inc. 1988-2001"};include kDefaultRsrcName  'vers' (2);		// Overall package//--------------------------------------------------------------------------------------------------// End of Moviewer.r